import { useRef, useState, type ReactNode } from 'react';
import { describedBy, FieldShell, useFieldIds } from '../../../primitives/field';
import { useControllableState } from '../../../primitives/use-controllable-state';
import './otp-input.css';

export interface OtpInputProps {
  label: ReactNode;
  hint?: ReactNode;
  error?: ReactNode;
  /** Number of characters in the code. */
  length?: number;
  /** `numeric` accepts digits; `alphanumeric` accepts letters and digits (shown in capitals). */
  mode?: 'numeric' | 'alphanumeric';
  value?: string;
  defaultValue?: string;
  onValueChange?: (value: string) => void;
  /** Called once the code reaches its full length. */
  onComplete?: (code: string) => void;
  /** Show dots instead of characters. */
  mask?: boolean;
  disabled?: boolean;
  name?: string;
  className?: string;
}

export function sanitizeCode(
  raw: string,
  length: number,
  mode: 'numeric' | 'alphanumeric',
): string {
  const allowed = mode === 'numeric' ? /\d/ : /[\dA-Za-z]/;
  return Array.from(raw)
    .filter((c) => allowed.test(c))
    .join('')
    .toUpperCase()
    .slice(0, length);
}

/**
 * A one-time code drawn as cells but typed into a single native input, so paste, SMS
 * autofill and password managers work, and screen readers hear one field, not six.
 */
export function OtpInput({
  label,
  hint,
  error,
  length = 6,
  mode = 'numeric',
  value,
  defaultValue = '',
  onValueChange,
  onComplete,
  mask = false,
  disabled = false,
  name,
  className,
}: OtpInputProps) {
  const ids = useFieldIds();
  const [code, setCode] = useControllableState({
    value,
    defaultValue: sanitizeCode(defaultValue, length, mode),
    onChange: onValueChange,
  });
  const [focused, setFocused] = useState(false);
  const inputRef = useRef<HTMLInputElement>(null);

  // Editing only happens at the end, so the caret cell is always the next empty one.
  const keepCaretAtEnd = () => {
    const input = inputRef.current;
    if (!input) return;
    const end = input.value.length;
    if (input.selectionStart !== end || input.selectionEnd !== end)
      input.setSelectionRange(end, end);
  };

  const activeIndex = Math.min(code.length, length - 1);

  return (
    <FieldShell
      ids={ids}
      label={label}
      hint={hint}
      error={error}
      className={['atl-otp', className].filter(Boolean).join(' ')}
    >
      <div
        className="atl-otp__frame"
        data-focused={focused || undefined}
        data-disabled={disabled || undefined}
      >
        <input
          ref={inputRef}
          id={ids.inputId}
          className="atl-otp__input"
          type="text"
          inputMode={mode === 'numeric' ? 'numeric' : 'text'}
          autoComplete="one-time-code"
          autoCapitalize="characters"
          autoCorrect="off"
          spellCheck={false}
          pattern={mode === 'numeric' ? '[0-9]*' : '[0-9A-Za-z]*'}
          // No maxLength: it would cut a pasted "123 456" before the separators are removed.
          value={code}
          disabled={disabled}
          name={name}
          aria-describedby={describedBy(ids, hint, error)}
          aria-invalid={error ? true : undefined}
          onChange={(event) => {
            const next = sanitizeCode(event.target.value, length, mode);
            setCode(next);
            if (next.length === length && next !== code) onComplete?.(next);
          }}
          onFocus={() => {
            setFocused(true);
            requestAnimationFrame(keepCaretAtEnd);
          }}
          onBlur={() => setFocused(false)}
          onSelect={keepCaretAtEnd}
          onClick={keepCaretAtEnd}
        />
        <div className="atl-otp__cells" aria-hidden="true">
          {Array.from({ length }, (_, index) => {
            const char = code[index];
            return (
              <span
                key={index}
                className="atl-otp__cell"
                data-filled={char ? '' : undefined}
                data-active={focused && index === activeIndex ? '' : undefined}
                data-gap={length >= 6 && index === length / 2 ? '' : undefined}
              >
                {char ? (mask ? '•' : char) : null}
              </span>
            );
          })}
        </div>
      </div>
    </FieldShell>
  );
}

@layer atlas.components {
  .atl-otp__frame {
    position: relative;
    width: fit-content;
    max-width: 100%;
  }

  /* The real input covers the cells but draws nothing; the cells draw its value. */
  .atl-otp__input {
    position: absolute;
    inset: 0;
    z-index: 1;
    width: 100%;
    padding: 0;
    border: 0;
    background: transparent;
    color: transparent;
    caret-color: transparent;
    font-size: 16px;
    letter-spacing: 1.5em;
    cursor: text;
  }

  .atl-otp__input::selection {
    background: transparent;
  }

  .atl-otp__input:focus-visible {
    outline: none;
  }

  .atl-otp__input:disabled {
    cursor: not-allowed;
  }

  .atl-otp__cells {
    display: flex;
    gap: var(--space-xs);
  }

  .atl-otp__cell {
    position: relative;
    display: grid;
    place-items: center;
    width: 3rem;
    height: 3.5rem;
    border-radius: var(--radius-control);
    background: var(--sea-1);
    box-shadow: inset 0 0 0 1px var(--edge);
    font-size: var(--step-2);
    font-weight: 600;
    font-variant-numeric: tabular-nums;
    transition:
      box-shadow var(--dur-tick) var(--ease-anchor),
      scale var(--dur-tick) var(--ease-anchor);
  }

  /* A visible break in the middle of six or more cells, like a printed code. */
  .atl-otp__cell[data-gap] {
    margin-left: var(--space-s);
  }

  .atl-otp__cell[data-filled] {
    background: var(--shoal);
  }

  .atl-otp__cell[data-active] {
    box-shadow:
      inset 0 0 0 2px var(--chart-magenta),
      0 0 0 3px var(--magenta-wash);
  }

  /* The caret: a bar in the next empty cell. */
  .atl-otp__cell[data-active]:not([data-filled])::after {
    content: '';
    width: 2px;
    height: 1.4rem;
    border-radius: 1px;
    background: var(--ink);
    animation: atl-otp-blink 1.1s steps(1) infinite;
  }

  @keyframes atl-otp-blink {
    50% {
      opacity: 0;
    }
  }

  .atl-otp[data-invalid] .atl-otp__cell {
    box-shadow: inset 0 0 0 2px var(--port);
  }

  .atl-otp__frame[data-disabled] .atl-otp__cells {
    opacity: 0.55;
  }

  @media (prefers-reduced-motion: reduce) {
    :root:not([data-motion='full']) .atl-otp__cell::after {
      animation: none;
    }
  }

  :root[data-motion='reduce'] .atl-otp__cell::after {
    animation: none;
  }

  @media (width < 30rem) {
    .atl-otp__cell {
      width: 2.5rem;
      height: 3rem;
    }
  }

  @media (forced-colors: active) {
    .atl-otp__cell {
      border: 1px solid FieldText;
    }
    .atl-otp__cell[data-active] {
      outline: 2px solid Highlight;
    }
  }
}
